package com.sigtm.backend.service;
import com.sigtm.backend.dto.*; import com.sigtm.backend.exception.*; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class CuentaPorPagarService {
 private final FacturaProveedorRepository invoices; private final PagoProveedorRepository payments; private final OrdenCompraRepository orders; private final AuditoriaService audit;
 @Transactional(readOnly=true) public List<FacturaProveedor> listar(){return invoices.findAll();}
 @Transactional public FacturaProveedor crear(CrearFacturaProveedorRequest r){ if(invoices.findByNumber(r.number().trim()).isPresent())throw new DuplicateResourceException("Número de factura de proveedor duplicado"); OrdenCompra o=orders.findDetailedById(r.purchaseOrderId()).orElseThrow(()->new ResourceNotFoundException("Orden de compra no encontrada")); if(!Set.of("RECIBIDA","PARCIAL").contains(o.getStatus()))throw new IllegalArgumentException("La orden debe tener una recepción"); if(invoices.findByPurchaseOrderId(o.getId()).isPresent())throw new IllegalArgumentException("La orden ya tiene factura de proveedor"); FacturaProveedor f=FacturaProveedor.builder().number(r.number().trim()).purchaseOrder(o).issueDate(r.issueDate()).dueDate(r.dueDate()).total(r.total()).balance(r.total()).status("PENDIENTE").build(); f=invoices.save(f); audit.registrar("CREATE","FACTURA_PROVEEDOR",f.getId(),"Factura proveedor "+f.getNumber()); return f; }
 @Transactional public FacturaProveedor pagar(Long id,RegistrarPagoProveedorRequest r){FacturaProveedor f=invoices.findById(id).orElseThrow(()->new ResourceNotFoundException("Factura de proveedor no encontrada")); if(r.amount().compareTo(f.getBalance())>0)throw new IllegalArgumentException("El pago supera el saldo"); payments.save(PagoProveedor.builder().supplierInvoice(f).amount(r.amount()).method(r.method().trim()).reference(r.reference()).paidAt(LocalDateTime.now()).build()); f.setBalance(f.getBalance().subtract(r.amount())); f.setStatus(f.getBalance().signum()==0?"PAGADA":"PARCIAL"); audit.registrar("UPDATE","FACTURA_PROVEEDOR",f.getId(),"Pago "+r.amount()+" para "+f.getNumber()); return invoices.save(f);}
}
